content.query:
let req = requests
| summarize requests = count(), server_errors = countif(toint(resultCode) >= 500), client_errors = countif(toint(resultCode) between (400 .. 499)), p95_ms = round(percentile(duration, 95), 1);
let exc = exceptions | where client_Type != "Browser" | summarize exceptions = count();
let dep = dependencies | where client_Type != "Browser"
| summarize failed_database_calls = countif(success == false and type contains "postgres"), failed_cache_calls = countif(success == false and type contains "redis");
req | extend key = 1
| join kind=fullouter (exc | extend key = 1) on key
| join kind=fullouter (dep | extend key = 1) on key
| project requests, server_errors, client_errors, p95_ms, exceptions, failed_database_calls, failed_cache_calls
